students = [
    {'name': 'Mal', 'class': 'Math', 'scores': [85, 92, 88, 90]},
    {'name': 'Zoe', 'class': 'Math', 'scores': [78, 82, 75, 80]},
    {'name': 'Wash', 'class': 'Math', 'scores': [92, 95, 88, 91]},
    {'name': 'Kaylee', 'class': 'Science', 'scores': [88, 85, 90, 87]},
    {'name': 'Inara', 'class': 'Science', 'scores': [72, 68, 70, 65]},
    {'name': 'Jayne', 'class': 'Science', 'scores': [95, 92, 94, 96]},
    {'name': 'Simon', 'class': 'English', 'scores': [88, 90, 85, 87]},
    {'name': 'River', 'class': 'English', 'scores': [65, 70, 68, 72]},
]

# Task 1: Calculate average for each student
averages = [sum(student['scores']) / len(student['scores']) for student in students]

# Task 2: Honor roll (average >= 85)
honor_roll = [
    student['name'] 
    for student in students 
    if sum(student['scores']) / len(student['scores']) >= 85
]

# Task 3: Group students by class
class_rosters = {
    class_name: [student['name'] for student in students if student['class'] == class_name]
    for class_name in set(student['class'] for student in students)
}

# Task 4: Performance categories
def get_category(avg):
    if avg >= 90:
        return 'Excellent'
    elif avg >= 80:
        return 'Good'
    elif avg >= 70:
        return 'Satisfactory'
    else:
        return 'Needs Improvement'

performance_report = {
    student['name']: get_category(sum(student['scores']) / len(student['scores']))
    for student in students
}

# Task 5: Flatten all scores
all_scores = [score for student in students for score in student['scores']]

